sparql:
PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
# Select year, total contributions that year, empirical contributions, and the resulting proportion
SELECT ?year (COUNT(?contribution) AS ?total) (SUM(?isEmpirical) AS ?empiricalCount) ((xsd:decimal(SUM(?isEmpirical)) / xsd:decimal(COUNT(?contribution))) AS ?proportion) WHERE {
  # Subquery: one row per contribution with flags for having real collection and real analysis
  {
    SELECT ?contribution (MAX(?c) AS ?hasCollection) (MAX(?a) AS ?hasAnalysis) WHERE {
      # Restrict to contributions of the Empirical Research Practice template
      ?contribution a orkgc:C27001 .
      # Data collection node present and not marked "no collection"
      OPTIONAL { ?contribution orkgp:P56008 ?dc . ?dc rdfs:label ?dcLabel . FILTER(LCASE(STR(?dcLabel)) != LCASE("no collection")) BIND(1 AS ?c) }
      # Data analysis node present and not marked "no analysis"
      OPTIONAL { ?contribution orkgp:P15124 ?da . ?da rdfs:label ?daLabel . FILTER(LCASE(STR(?daLabel)) != LCASE("no analysis")) BIND(1 AS ?a) }
    } GROUP BY ?contribution
  }
  # Link contribution to its publication
  ?paper orkgp:P31 ?contribution .
  # Publication year of the paper
  ?paper orkgp:P29 ?year .
  # Empirical study = has data collection AND data analysis
  BIND(IF(?hasCollection = 1 && ?hasAnalysis = 1, 1, 0) AS ?isEmpirical)
} GROUP BY ?year ORDER BY ?year

PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
# Select year, total contributions, non-empirical contributions, and their proportion
SELECT ?year (COUNT(?contribution) AS ?total) (SUM(?nonEmpirical) AS ?nonEmpiricalCount) ((xsd:decimal(SUM(?nonEmpirical)) / xsd:decimal(COUNT(?contribution))) AS ?proportion) WHERE {
  # Subquery: one row per contribution with flags for empirical data collection and analysis
  {
    SELECT ?contribution (MAX(?c) AS ?hasCollection) (MAX(?a) AS ?hasAnalysis) WHERE {
      # Restrict to contributions of the Empirical Research Practice template
      ?contribution a orkgc:C27001 .
      # Data collection present and not "no collection"
      OPTIONAL { ?contribution orkgp:P56008 ?dc . ?dc rdfs:label ?dcLabel . FILTER(LCASE(STR(?dcLabel)) != LCASE("no collection")) BIND(1 AS ?c) }
      # Data analysis present and not "no analysis"
      OPTIONAL { ?contribution orkgp:P15124 ?da . ?da rdfs:label ?daLabel . FILTER(LCASE(STR(?daLabel)) != LCASE("no analysis")) BIND(1 AS ?a) }
    } GROUP BY ?contribution
  }
  # Link contribution to publication
  ?paper orkgp:P31 ?contribution .
  # Publication year
  ?paper orkgp:P29 ?year .
  # Non-empirical = lacks a real data collection or lacks a real analysis
  BIND(IF(?hasCollection = 1 && ?hasAnalysis = 1, 0, 1) AS ?nonEmpirical)
} GROUP BY ?year ORDER BY ?year

PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
# Select year with counts of each reported threat-to-validity type and the share of papers reporting any
SELECT ?year (COUNT(?contribution) AS ?total) (SUM(?anyThreat) AS ?withAnyThreat) ((xsd:decimal(SUM(?anyThreat)) / xsd:decimal(COUNT(?contribution))) AS ?proportion) (SUM(?external) AS ?externalValidity) (SUM(?internal) AS ?internalValidity) (SUM(?construct) AS ?constructValidity) (SUM(?conclusion) AS ?conclusionValidity) (SUM(?reliability) AS ?reliability) (SUM(?generalizability) AS ?generalizability) (SUM(?repeatability) AS ?repeatability) (SUM(?content) AS ?contentValidity) (SUM(?descriptive) AS ?descriptiveValidity) (SUM(?theoretical) AS ?theoreticalValidity) (SUM(?mentioned) AS ?mentionedOnly) WHERE {
  # Subquery: one row per contribution with a flag per threat-to-validity type
  {
    SELECT ?contribution (MAX(?extF) AS ?external) (MAX(?intF) AS ?internal) (MAX(?consF) AS ?construct) (MAX(?conclF) AS ?conclusion) (MAX(?relF) AS ?reliability) (MAX(?genF) AS ?generalizability) (MAX(?repF) AS ?repeatability) (MAX(?contF) AS ?content) (MAX(?descF) AS ?descriptive) (MAX(?theoF) AS ?theoretical) (MAX(?mentF) AS ?mentioned) (MAX(?anyF) AS ?anyThreat) WHERE {
      # Restrict to contributions of the Empirical Research Practice template
      ?contribution a orkgc:C27001 .
      # Threats to validity node of the contribution
      ?contribution orkgp:P39099 ?threats .
      # External validity reported
      OPTIONAL { ?threats orkgp:P55034 ?v1 . BIND(IF(?v1 = true,1,0) AS ?extF) }
      # Internal validity reported
      OPTIONAL { ?threats orkgp:P55035 ?v2 . BIND(IF(?v2 = true,1,0) AS ?intF) }
      # Construct validity reported
      OPTIONAL { ?threats orkgp:P55037 ?v3 . BIND(IF(?v3 = true,1,0) AS ?consF) }
      # Conclusion validity reported
      OPTIONAL { ?threats orkgp:P55036 ?v4 . BIND(IF(?v4 = true,1,0) AS ?conclF) }
      # Reliability reported
      OPTIONAL { ?threats orkgp:P59109 ?v5 . BIND(IF(?v5 = true,1,0) AS ?relF) }
      # Generalizability reported
      OPTIONAL { ?threats orkgp:P60006 ?v6 . BIND(IF(?v6 = true,1,0) AS ?genF) }
      # Repeatability reported
      OPTIONAL { ?threats orkgp:P97002 ?v7 . BIND(IF(?v7 = true,1,0) AS ?repF) }
      # Content validity reported
      OPTIONAL { ?threats orkgp:P68005 ?v8 . BIND(IF(?v8 = true,1,0) AS ?contF) }
      # Descriptive validity reported
      OPTIONAL { ?threats orkgp:P97000 ?v9 . BIND(IF(?v9 = true,1,0) AS ?descF) }
      # Theoretical validity reported
      OPTIONAL { ?threats orkgp:P97001 ?v10 . BIND(IF(?v10 = true,1,0) AS ?theoF) }
      # Threats mentioned but not classified
      OPTIONAL { ?threats orkgp:P145000 ?v11 . BIND(IF(?v11 = true,1,0) AS ?mentF) }
      # Any reported threat at all
      BIND(IF(COALESCE(?extF,0)+COALESCE(?intF,0)+COALESCE(?consF,0)+COALESCE(?conclF,0)+COALESCE(?relF,0)+COALESCE(?genF,0)+COALESCE(?repF,0)+COALESCE(?contF,0)+COALESCE(?descF,0)+COALESCE(?theoF,0)+COALESCE(?mentF,0) > 0, 1, 0) AS ?anyF)
    } GROUP BY ?contribution
  }
  # Link contribution to publication
  ?paper orkgp:P31 ?contribution .
  # Publication year
  ?paper orkgp:P29 ?year .
} GROUP BY ?year ORDER BY ?year

PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
# Select year with counts of papers reporting research questions and answers, split by hidden/highlighted
SELECT ?year (COUNT(?contribution) AS ?total) (SUM(?hasRQ) AS ?withResearchQuestion) (SUM(?hasAnswer) AS ?withAnswer) (SUM(?rqHidden) AS ?rqHiddenInText) (SUM(?rqHighlighted) AS ?rqHighlightedInText) (SUM(?ansHidden) AS ?answerHiddenInText) (SUM(?ansHighlighted) AS ?answerHighlightedInText) WHERE {
  # Subquery: one row per contribution with reporting flags for questions and answers
  {
    SELECT ?contribution (MAX(?rqExist) AS ?hasRQ) (MAX(?ansExist) AS ?hasAnswer) (MAX(?h1) AS ?rqHidden) (MAX(?g1) AS ?rqHighlighted) (MAX(?h2) AS ?ansHidden) (MAX(?g2) AS ?ansHighlighted) WHERE {
      # Restrict to contributions of the Empirical Research Practice template
      ?contribution a orkgc:C27001 .
      # Research question nodes with existence and presentation flags
      OPTIONAL {
        ?contribution orkgp:P37330 ?rq .
        BIND(1 AS ?rqExist)
        # Whether the question is hidden in the text
        OPTIONAL { ?rq orkgp:P55038 ?rqHiddenRaw . BIND(IF(?rqHiddenRaw = true,1,0) AS ?h1) }
        # Whether the question is highlighted in the text
        OPTIONAL { ?rq orkgp:P55039 ?rqHighRaw . BIND(IF(?rqHighRaw = true,1,0) AS ?g1) }
      }
      # Research question answer nodes with existence and presentation flags
      OPTIONAL {
        ?contribution orkgp:P57004 ?answer .
        BIND(1 AS ?ansExist)
        # Whether the answer is hidden in the text
        OPTIONAL { ?answer orkgp:P55038 ?ansHiddenRaw . BIND(IF(?ansHiddenRaw = true,1,0) AS ?h2) }
        # Whether the answer is highlighted in the text
        OPTIONAL { ?answer orkgp:P55039 ?ansHighRaw . BIND(IF(?ansHighRaw = true,1,0) AS ?g2) }
      }
    } GROUP BY ?contribution
  }
  # Link contribution to publication
  ?paper orkgp:P31 ?contribution .
  # Publication year
  ?paper orkgp:P29 ?year .
} GROUP BY ?year ORDER BY ?year
